try (JarFile jar = new JarFile(path.toFile())) {
    jar.stream()
       .filter(e -> e.getName().endsWith(".class"))
       .forEach(e -> {
           try (InputStream in = jar.getInputStream(e)) {
               // 1. read magic, minor, major from the first 10 bytes
               ClassFileFacts.Header h = ClassFileFacts.header(in.readNBytes(10));
               // 2. report anything newer than the runtime
               if (h.major() > 65) System.out.println(e.getName() + " -> Java " + ClassFileFacts.javaVersion(h.major()));
           } catch (IOException ex) {
               throw new UncheckedIOException(ex);
           }
